{
  "title": "Discussion on tax filing, domain purchase, and app viability",
  "topics": [
    {
      "id": "tax-filing",
      "title": "Tax filing and declaration issues",
      "claims": [
        {
          "text": "User U1 paid ~500 UAH to aunt Sveta to correct a large tax declaration error caused by mislabelled columns.",
          "evidence": [1]
        },
        {
          "text": "U1's inspector ignored declarations for 1.5 years and only later demanded re‑verification of all years, leading to a correct re‑submission costing about 1000 UAH.",
          "evidence": [1]
        },
        {
          "text": "The tax calculation procedure takes about an hour with Excel, possibly a day per month.",
          "evidence": [5,6]
        },
        {
          "text": "Quarterly reports must be filed correctly to avoid penalties.",
          "evidence": [7]
        },
        {
          "text": "Mistakes in column selection dramatically affect tax amounts, often by several thousand hryvnias.",
          "evidence": [8]
        }
      ]
    },
    {
      "id": "domain-purchase",
      "title": "Domain purchase considerations",
      "claims": [
        {
          "text": "U2 has not bought a domain yet.",
          "evidence": [2]
        },
        {
          "text": "U4 doubts buying a domain, calling it a “silly thing” that won’t be profitable.",
          "evidence": [9,10]
        },
        {
          "text": "U1 suggests that buying a tax calculator could free money for a domain.",
          "evidence": [4]
        }
      ]
    },
    {
      "id": "app-profitability",
      "title": "Viability of a cross‑platform app",
      "claims": [
        {
          "text": "U1 reports that web platforms are less profitable than Android/iOS, with poor SEO and no passive ad revenue.",
          "evidence": [11]
        },
        {
          "text": "A successful approach cited involves fast delivery (< 1 week) using a cross‑platform stack like Flutter and copying popular ideas.",
          "evidence": [12]
        },
        {
          "text": "U4 questions the audience size, asking if there are at least ten people willing to pay 299 UAH.",
          "evidence": [20]
        },
        {
          "text": "U1 wonders if the source code could be found by searching for the password.",
          "evidence": [21]
        }
      ]
    },
    {
      "id": "scam-concerns",
      "title": "Potential scam and security doubts",
      "claims": [
        {
          "text": "U4 suspects the project is a scam, calling it “local‑first app” with minimal features and a hidden password for a 100 % discount.",
          "evidence": [30,32]
        },
        {
          "text": "U5 labels the offer as “pirate” and confirms it’s a scam.",
          "evidence": [24,33]
        },
        {
          "text": "U1 jokingly claims most LinkedIn users could hack the app easily.",
          "evidence": [28]
        }
      ]
    }
  ],
  "decisions": [],
  "openQuestions": []
}
